#!/usr/bin/env node
// Bundles the web help articles (web/src/docs/strategy/NN-slug.md) into src/content/strategyDocs.ts
// and the SDK API reference (web/src/docs/sdk.json, generated by strategies/ctg/sdkdoc.py) into
// src/content/sdkRef.ts, so they ship with the JS bundle (and OTA updates). Run after the web docs change:
//   node mobile/scripts/gen-docs.mjs
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const src = join(here, "../../web/src/docs/strategy");
const out = join(here, "../src/content/strategyDocs.ts");

const docs = readdirSync(src)
  .filter((f) => /^\d+-.+\.md$/.test(f))
  .sort()
  .map((f) => {
    const raw = readFileSync(join(src, f), "utf8");
    const m = raw.match(/^---\n([\s\S]*?)\n---\n?/);
    const front = Object.fromEntries((m?.[1] ?? "").split("\n").map((l) => l.match(/^(\w+):\s*(.*)$/)).filter(Boolean).map((x) => [x[1], x[2].trim()]));
    return { slug: f.replace(/^\d+-/, "").replace(/\.md$/, ""), title: front.title ?? f, summary: front.summary ?? "", body: m ? raw.slice(m[0].length) : raw };
  });

writeFileSync(
  out,
  `// Generated by scripts/gen-docs.mjs from web/src/docs/strategy/*.md — do not edit by hand.\n` +
    `export interface Doc { slug: string; title: string; summary: string; body: string }\n\n` +
    `export const strategyDocs: Doc[] = ${JSON.stringify(docs, null, 1)};\n`,
);
console.log(`wrote ${docs.length} articles → ${out}`);

const sdk = JSON.parse(readFileSync(join(here, "../../web/src/docs/sdk.json"), "utf8"));
const sdkOut = join(here, "../src/content/sdkRef.ts");
writeFileSync(
  sdkOut,
  `// Generated by scripts/gen-docs.mjs from web/src/docs/sdk.json — do not edit by hand.\n` +
    `export interface SdkEntry { group: string; name: string; kind: string; sig: string; doc: string }\n\n` +
    `export const sdkRef: SdkEntry[] = ${JSON.stringify(sdk.map(({ group, name, kind, sig, doc }) => ({ group, name, kind, sig, doc })), null, 1)};\n`,
);
console.log(`wrote ${sdk.length} SDK entries → ${sdkOut}`);
